cases.source:
_RATE = 0.9
def eligible(total: int) -> bool:
    return total >= 100

cases.tests:
import assert from 'node:assert/strict';
import * as target from './target.ts';
assert.equal(target.eligible(100), true);

import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import * as target from './target.ts';
const value = target.enabled();
if (!value) spawnSync('echo', ['blocked']);
assert.equal(value, true);

import { existsSync, writeFileSync } from 'node:fs';
import * as target from './target.ts';
const state = {state_path};
if (!existsSync(state)) { target.enabled(); writeFileSync(state, 'visited'); }

import assert from 'node:assert/strict';
import * as target from './target.ts';
assert.equal(target._RATE, 0.9);
assert.equal(target.eligible(100), true);
